def transform(grid):
    """For each 1-outline enclosing a zero region, color its inner and outer halos."""
    h, w = len(grid), len(grid[0])
    dirs4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    dirs8 = tuple((dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                  if (dr, dc) != (0, 0))

    # Label 4-connected 1-components, since diagonally touching strokes need
    # not form one continuous outline.
    labels = [[-1] * w for _ in range(h)]
    ncomp = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or labels[r][c] >= 0:
                continue
            labels[r][c] = ncomp
            queue = deque([(r, c)])
            while queue:
                x, y = queue.popleft()
                for dx, dy in dirs4:
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and labels[nx][ny] < 0):
                        labels[nx][ny] = ncomp
                        queue.append((nx, ny))
            ncomp += 1

    # Flood-fill zero regions on a padded grid. Any region not connected to
    # the padded exterior is a cavity enclosed by one or more 1-components.
    padded = [[0] * (w + 2) for _ in range(h + 2)]
    for r in range(h):
        padded[r + 1][1:w + 1] = grid[r][:]
    exterior = {(0, 0)}
    queue = deque([(0, 0)])
    while queue:
        r, c = queue.popleft()
        for dr, dc in dirs4:
            nr, nc = r + dr, c + dc
            if (0 <= nr < h + 2 and 0 <= nc < w + 2
                    and padded[nr][nc] == 0 and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    # Identify which 1-components actually border an enclosed zero region.
    cavity_cells = set()
    eligible_components = set()
    visited = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r + 1, c + 1) in exterior or (r, c) in visited:
                continue
            region = []
            queue = deque([(r, c)])
            visited.add((r, c))
            while queue:
                x, y = queue.popleft()
                region.append((x, y))
                for dx, dy in dirs4:
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx + 1, ny + 1) not in exterior
                            and (nx, ny) not in visited):
                        visited.add((nx, ny))
                        queue.append((nx, ny))
            cavity_cells.update(region)
            for x, y in region:
                for dx, dy in dirs8:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and labels[nx][ny] >= 0:
                        eligible_components.add(labels[nx][ny])

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            adjacent_eligible = any(
                0 <= r + dr < h and 0 <= c + dc < w
                and labels[r + dr][c + dc] in eligible_components
                for dr, dc in dirs8
            )
            if not adjacent_eligible:
                continue
            if (r, c) in cavity_cells:
                result[r][c] = 3
            elif (r + 1, c + 1) in exterior:
                result[r][c] = 2
    return result
